import { test } from "node:test";
import assert from "node:assert/strict";
import { canShip } from "../src/deploy.ts";

test("Monday 10am UTC is a valid deployment window", () => {
  const monday = new Date("2026-11-16T10:00:00Z"); // Monday
  assert.equal(canShip(monday), true);
});

test("Tuesday 15pm UTC is a valid deployment window", () => {
  const tuesday = new Date("2026-11-17T15:00:00Z"); // Tuesday
  assert.equal(canShip(tuesday), true);
});

test("Friday 10am UTC is allowed", () => {
  const friday = new Date("2026-11-20T10:00:00Z"); // Friday
  assert.equal(canShip(friday), true);
});

test("Friday 15pm UTC is blocked", () => {
  const friday = new Date("2026-11-20T15:00:00Z"); // Friday afternoon
  assert.equal(canShip(friday), false);
});

test("Saturday is blocked", () => {
  const saturday = new Date("2026-11-21T10:00:00Z"); // Saturday
  assert.equal(canShip(saturday), false);
});

test("Sunday is blocked", () => {
  const sunday = new Date("2026-11-22T10:00:00Z"); // Sunday
  assert.equal(canShip(sunday), false);
});

test("Monday 7am UTC is blocked (too early)", () => {
  const monday = new Date("2026-11-16T07:00:00Z");
  assert.equal(canShip(monday), false);
});

test("Monday 19pm UTC is blocked (too late)", () => {
  const monday = new Date("2026-11-16T19:00:00Z");
  assert.equal(canShip(monday), false);
});

test("Thursday 8am UTC is allowed (start of window)", () => {
  const thursday = new Date("2026-11-19T08:00:00Z");
  assert.equal(canShip(thursday), true);
});

test("Thursday 18:59 UTC is allowed (end of window)", () => {
  const thursday = new Date("2026-11-19T18:59:00Z");
  assert.equal(canShip(thursday), true);
});

